/* Auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }];
}
return [{ json: { ok: true } }];

/* L2 registry: user-built n8n workflows exposed as chat tools (list / register / toggle). */
const req = $('Webhook Tools').first().json;
const body = req.body || {};
const action = String(body.action || 'list');
const N8N = 'http://localhost:5678/api/v1';
const apiJson = (method, path, qs, b) => this.helpers.httpRequest({ method, url: N8N + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: b, timeout: 15000 });
const tables = await apiJson('GET', '/data-tables', { limit: 100 });
let tid = ((tables.data) || []).find((t) => t.name === 'workflow_tools')?.id;
if (!tid) {
  const t = await apiJson('POST', '/data-tables', null, { name: 'workflow_tools', columns: [{ name: 'name', type: 'string' }, { name: 'title', type: 'string' }, { name: 'description', type: 'string' }, { name: 'path', type: 'string' }, { name: 'enabled', type: 'number' }, { name: 'created_via', type: 'string' }] });
  tid = t && t.id;
}
if (!tid) return [{ json: { ok: false, error: 'registry unavailable' } }];
const rowsOf = async () => (((await apiJson('GET', '/data-tables/' + tid + '/rows', { limit: 250 })).data) || []);
const delByName = async (name) => {
  const filter = encodeURIComponent(JSON.stringify({ type: 'and', filters: [{ columnName: 'name', condition: 'eq', value: name }] }));
  await this.helpers.httpRequest({ method: 'DELETE', url: N8N + '/data-tables/' + tid + '/rows/delete?filter=' + filter, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 }).catch(() => {});
};

if (action === 'list') {
  const rows = (await rowsOf()).filter((r) => Number(r.enabled) === 1);
  return [{ json: { ok: true, tools: rows.map((r) => ({ name: r.name, title: r.title, description: r.description, path: r.path })) } }];
}
if (action === 'register' || action === 'update') {
  const name = String(body.name || '').trim().toLowerCase();
  const path0 = String(body.path || '').trim().replace(/^https?:\/\/[^/]+\/webhook\//, '').replace(/^\/?webhook\//, '').replace(/^\//, '');
  if (!/^[a-z0-9_-]{2,32}$/.test(name)) return [{ json: { ok: false, error: 'name must match [a-z0-9_-]{2,32}' } }];
  if (!/^[-a-zA-Z0-9_/]{2,80}$/.test(path0)) return [{ json: { ok: false, error: 'path invalid' } }];
  const RESERVED = ['v1', 'internal', 'mcp', 'admin/tools'];
  if (RESERVED.some((x) => path0 === x || path0.startsWith(x + '/'))) {
    const okReserved = path0 === 'admin/tools' ? false : true;
    if (!okReserved || path0 === 'v1' || path0 === 'mcp' || path0.startsWith('internal/')) return [{ json: { ok: false, error: 'path reserved: ' + path0 } }];
  }
  await delByName(name);
  await apiJson('POST', '/data-tables/' + tid + '/rows', null, { data: [{ name, title: String(body.title || name).slice(0, 60), description: String(body.description || '').slice(0, 300), path: path0, enabled: body.enabled === 0 ? 0 : 1, created_via: String(body.via || 'api').slice(0, 20) }] });
  return [{ json: { ok: true, registered: name, path: path0 } }];
}
if (action === 'toggle') {
  const name = String(body.name || '').trim().toLowerCase();
  const rows = await rowsOf();
  const row = rows.find((r) => String(r.name) === name);
  if (!row) return [{ json: { ok: false, error: 'not found: ' + name } }];
  await delByName(name);
  await apiJson('POST', '/data-tables/' + tid + '/rows', null, { data: [{ name, title: row.title, description: row.description, path: row.path, enabled: body.enabled === 0 ? 0 : 1, created_via: row.created_via || 'api' }] });
  return [{ json: { ok: true, toggled: name, enabled: body.enabled === 0 ? 0 : 1 } }];
}
return [{ json: { ok: false, error: 'unknown action: ' + action } }];
